struct ggml_tensor {
    int op;
    int32_t op_params[4];
    ggml_tensor * src[4];
    char name[64];
    int64_t ne[4];
    int flags;

    ggml_tensor() : op(0) {
        memset(op_params, 0, sizeof(op_params));
        memset(src, 0, sizeof(src));
